--- a/src/main/java/com/studymate/attendance/AttendanceService.java
+++ b/src/main/java/com/studymate/attendance/AttendanceService.java
@@ -1,6 +1,17 @@
 package com.studymate.attendance;

 @Service
 @RequiredArgsConstructor
 public class AttendanceService {
+    private final AttendanceRepository attendances;
+    private final SessionRepository sessions;
+
+    @Transactional
+    public Attendance checkIn(Long sessionId, Long memberId) {
+        Session session = sessions.findById(sessionId).orElseThrow();
+        Attendance attendance = attendances.findBySessionIdAndMemberId(sessionId, memberId)
+            .orElseGet(() -> new Attendance(sessionId, memberId));
+        attendance.checkIn(Instant.now());
+        return attendances.save(attendance);
+    }
 }
